import * as THREE from 'three';
import reference from '../data/cft70-reference.json' with { type: 'json' };

export { reference };

// Every value, level and alert comes from the HealthService (GET /api/v1/analyses); this module only turns them
// into colours and text. Reference data (CFT70) is static, generated by scripts/build-cft70-reference.py.
export const referenceFor = measure => reference.tests.find(test => test.measure === measure) ?? null;

// Level colours, green (no clear change) to red (large loss). Lightness falls with severity so the order reads
// without telling colours apart, and they always go with text. Checked with the dataviz colour-blindness check.
export const LEVEL_COLORS = { 1: '#8fcca5', 2: '#d7a12a', 3: '#d1602b', 4: '#a4242f' };
export const NOT_MEASURED = '#d6d9dc';
export const levelColor = level => LEVEL_COLORS[level] ?? NOT_MEASURED;
const threeColors = [1, 2, 3, 4].map(level => new THREE.Color(LEVEL_COLORS[level]));
// score = position on the scale (1 to 4). In-between values only appear while the body moves from one
// evaluation to another, and blend the two neighbouring levels.
export const colorScale = score => {
  const t = Math.max(1, Math.min(4, score)) - 1, i = Math.min(2, Math.floor(t));
  return threeColors[i].clone().lerp(threeColors[i + 1], t - i);
};

export const fmtPct = value => value == null ? '—' : `${value > 0 ? '+' : value < 0 ? '−' : ''}${Math.abs(value).toFixed(1)}%`;
export const fmtNum = (value, digits = 1) => value == null ? '—' : value.toFixed(digits);

// Charts put the pre-flight reference at x = 0, then mission days; labels as NASA writes them.
export const xOf = evaluation => evaluation.phase === 'pre' ? 0 : evaluation.day;
export const dayLabel = (day, landing) => day === 0 ? 'Pre' : day < landing ? `FD${Math.floor(day) + 1}` : `R+${Math.floor(day - landing)}`;
export function dayAxis(mission, days) {
  const end = Math.max(mission.landing, ...days);
  const step = end > 240 ? 60 : 30;
  const ticks = [];
  for (let d = 0; d <= end; d += step) ticks.push(d);
  return { domain: [0, end], ticks };
}

// Text of a test's level: NASA's minimum takes over the label when it is the reason for level 4.
export function levelText(point, levels) {
  if (point.level == null) return point.quality === 'not measured' ? 'Not measured' : `No valid test (${point.quality.replaceAll('_', ' ')})`;
  if (point.belowMinimum) return 'Below NASA minimum';
  return levels.find(item => item.level === point.level)?.label ?? `Level ${point.level}`;
}

export const ALERT_TEXT = { critical: 'NASA standard crossed', warning: 'Faster loss than expected' };
